class Solution {
public:
    int maxJump(std::vector<int>& stones) {
        if (stones.size() == 2) return stones[1] - stones[0];
        int ans = stones[1] - stones[0];
        for (int i = 2; i < (int)stones.size(); ++i) {
            ans = std::max(ans, stones[i] - stones[i - 2]);
        }
        return ans;
    }
};

class Solution {
    public int maxJump(int[] stones) {
        if (stones.length == 2) return stones[1] - stones[0];
        int ans = stones[1] - stones[0];
        for (int i = 2; i < stones.length; i++) {
            ans = Math.max(ans, stones[i] - stones[i - 2]);
        }
        return ans;
    }
}

var maxJump = function(stones) {
    if (stones.length === 2) return stones[1] - stones[0];
    let ans = stones[1] - stones[0];
    for (let i = 2; i < stones.length; i++) {
        const step = stones[i] - stones[i - 2];
        if (step > ans) ans = step;
    }
    return ans;
};
